"""Build a schema contract; not a SharePoint site or a Canvas import package."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def field(name,label,kind='Text',required=False,indexed=False,unique=False,allowed=None):
    return dict(name=name,label=label,type=kind,required=required,indexed=indexed,unique=unique,**({'allowed':allowed} if allowed else {}))
assets=[field('AssetKey','자산 키',required=True,indexed=True,unique=True),field('SerialNumber','S/N 원문',required=True),field('SerialKey','S/N 정규화 키',required=True,indexed=True,unique=True)]
for name,label in [('SAPAssetNumber','SAP 자산번호'),('PCName','PC 이름'),('Model','모델'),('AssignedUserKOR','사용자'),('AssignedUserENG','영문 사용자'),('ADAccount','AD 계정'),('LocationKey','표준 위치'),('LocationRaw','원본 위치'),('LocationDetail','상세 위치'),('DeviceTypeRaw','원본 종류'),('LanConnectorRaw','LAN 지급 원문'),('ConsumablesRaw','소모품 지급 원문'),('ChecklistRaw','창고 체크 원문'),('LegacyNo','원본 No.'),('SourceSheet','원본 시트'),('LegacyStartText','원본 시작일'),('LegacyExpiryText','원본 만료일'),('LegacyRemainingText','원본 잔여개월'),('LastRequestId','마지막 저장 요청 키')]:
    assets.append(field(name,label,indexed=name in ['SAPAssetNumber','PCName','Model','AssignedUserKOR','LocationKey']))
assets += [field('AssetGroup','사용 구분',required=True,indexed=True,allowed=['Office','Shared','Plant','Unassigned']),field('LifecycleState','운영 상태',required=True,indexed=True,allowed=['InUse','Stock','Retired']),field('DeviceType','장비 종류',required=True,indexed=True,allowed=['Laptop','Desktop','Other','Unknown']),field('AcquisitionState','취득 상태',allowed=['Acquired','Unacquired','Unknown']),field('ExpirySource','만료일 근거',allowed=['Explicit','Derived','Unknown'])]
assets += [field(n,l,'Date',indexed=n=='ExpiryDate') for n,l in [('StartDate','시작일'),('ExpiryDate','확정/산출 만료일'),('RetiredOn','폐기 확인일')]]
assets += [field('UsageMonths','사용기간(개월)','Number'),field('HasExpiry','만료일 있음','Boolean',True,True),field('HasDataIssues','점검 필요','Boolean',True,True),field('IsDeleted','논리 삭제','Boolean',True,True),field('SourceRow','원본 행','Number')]
assets += [field(n,l,'Note') for n,l in [('Remarks','비고'),('IssueCodes','점검 코드'),('LegacyMetadata','원본 값/수식 보존 JSON')]]
def make(name,description,fields,phase='Core'):
    return {'name':name,'description':description,'phase':phase,'versioning':True,'titleRequired':False,'fields':fields}
lists=[make('ITAssets','자산 마스터. 폐기 자산도 동일 목록에 유지.',assets),make('ITAssetStaging','전체 원본 행과 검토 결과. 중복 S/N도 보존.',[field('SourceKey','이관 키',required=True,unique=True,indexed=True),field('SerialKey','정규화 S/N',indexed=True),field('ReviewState','검토 상태',indexed=True,allowed=['Ready','NeedsSerialReview','Approved','Rejected']),field('SourceSheet','시트'),field('SourceRow','행','Number'),field('IssueCodes','점검 코드','Note'),field('ProposedAsset','마스터 제안 JSON','Note'),field('LegacyMetadata','원본 값/수식 JSON','Note')]),make('ITLocations','위치 필터의 기준 목록. 자산 Distinct 집계 대신 사용.',[field('LocationKey','위치 코드','Text',True,True,True),field('SortOrder','정렬','Number'),field('SelectableForAsset','자산 선택 가능','Boolean',True,True)]),make('ITAssetSummary','서버 페이지 순회 집계. Canvas CountRows 전체 합산 금지.',[field('SummaryKey','집계 키',required=True,indexed=True,unique=True),field('BusinessDate','기준 날짜','Date'),field('CalculatedAt','집계 시각','DateTime'),field('CountsJson','전체 집계 JSON','Note'),field('Complete','집계 완전성','Boolean')]),make('ITAssetEvents','업무 이벤트. SharePoint 기본 버전 이력과 함께 사용.',[field('RequestId','요청 키',required=True,indexed=True,unique=True),field('AssetId','마스터 ID','Number',True,True),field('ActionCode','업무 유형'),field('ActorUPN','요청 사용자'),field('FromState','이전 상태'),field('ToState','새 상태'),field('Notes','사유','Note'),field('EventTime','처리 시각','DateTime')])]
lists += [make('ITSAPBatches','SAP 업로드 작업 상태. 기준 회계 시트는 하나만 선택.',[field('BatchKey','배치 키',required=True,indexed=True,unique=True),field('Ledger','회계 시트'),field('ProcessingState','처리 상태',indexed=True),field('FileName','파일명'),field('SnapshotTime','스냅샷 시각','DateTime'),field('RequestedBy','요청자'),field('AssetRevision','IT 목록 대조 기준'),field('CountsJson','집계','Note')],'Phase2'),make('ITSAPResults','서버/로컬 대조 결과. 대량 대조를 Canvas ForAll로 처리하지 않음.',[field('ResultKey','결과 키',required=True,indexed=True,unique=True),field('BatchKey','배치 키','Text',True,True),field('StatusCode','결과 코드',indexed=True),field('SerialKey','S/N',indexed=True),field('SAPAssetNumber','SAP 번호'),field('Direction','대조 방향'),field('SourceRow','SAP 원본 행','Number'),field('Description','설명','Note'),field('MatchAssetIds','발견 ID JSON','Note'),field('Notes','확인 사항','Note')],'Phase2')]
obj={'schemaVersion':'1.0','listNamesAreStable':True,'fieldNamesAreInternalNames':True,'categoryFieldsAreTextForDelegation':True,'dateTimezone':'date-only business dates; SharePoint site timezone Asia/Seoul','lists':lists,'libraries':[{'name':'ITAssetImports','phase':'Phase2','description':'사내 SAP 파일/검토 결과 전용. 실제 회사 파일은 승인된 사내 사이트만 사용.'}]}
(ROOT/'schema/sharepoint-lists.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf-8')
if __name__=='__main__':print('Created schema contract')
